"""Record build/test inputs for this task without accessing another checkout."""
import hashlib
import json
import subprocess
import sys
from datetime import datetime, timezone
from pathlib import Path

root = Path(__file__).resolve().parent.parent
tracked = subprocess.check_output(['git', 'ls-files', '-z'], cwd=root).decode().split('\0')
paths = {name for name in tracked if name and name != 'AGENTS.md'}
for folder in ('entry/src', 'hypium_tests'):
    for path in (root / folder).rglob('*'):
        if path.is_file() and '__pycache__' not in path.parts:
            paths.add(path.relative_to(root).as_posix())
files = {name: hashlib.sha256((root / name).read_bytes()).hexdigest()
         for name in sorted(paths) if (root / name).is_file()}
digest = hashlib.sha256(json.dumps(files, sort_keys=True).encode()).hexdigest()
result = {'utc': datetime.now(timezone.utc).isoformat(),
          'head': subprocess.check_output(['git', 'rev-parse', 'HEAD'], cwd=root).decode().strip(),
          'source_sha256': digest, 'files': files}
destination = root / sys.argv[1]
destination.parent.mkdir(parents=True, exist_ok=True)
destination.write_text(json.dumps(result, indent=2), encoding='utf-8')
print(json.dumps({'path': str(destination), 'source_sha256': digest, 'count': len(files)}))

