"""Use the unchanged common runner, selecting local debugging cases by name."""
import os
import sys
import unittest
import harness.runner as runner

original = runner.discover
selection = os.environ.get("VG14_CASE_FILTER", "")

def flatten(suite):
    for case in suite:
        if isinstance(case, unittest.TestSuite):
            yield from flatten(case)
        else:
            yield case

def discover(project):
    return unittest.TestSuite(case for case in flatten(original(project)) if selection in str(case))

runner.discover = discover
sys.exit(runner.main())

